/* @autogenerated */
import { Component, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { provideRouter, Router } from '@angular/router';
import { AppStateService } from '@shared/context/state/app-state.service';
import { WORKSPACES, WorkspaceStateService } from './workspace-state.service';
import { workspaceRoutes } from './workspace.routes';
import { WorkspaceDefinition } from './workspace.model';

@Component({ template: '' })
class PageComponent {}

const page = () => [{ path: 'clients', component: PageComponent }];
const MAIN: WorkspaceDefinition = {
  name: 'main',
  path: '',
  label: 'Main',
  selectors: [],
  nav: [{ label: 'Clients', route: 'clients' }],
  userMenu: [],
  routes: page,
};
const ADMIN: WorkspaceDefinition = { ...MAIN, name: 'admin', path: '@admin', label: 'Admin', nav: [] };

describe('WorkspaceStateService', () => {
  let contextScope: ReturnType<typeof signal<string>>;

  beforeEach(() => {
    contextScope = signal('');
    TestBed.configureTestingModule({
      providers: [
        { provide: WORKSPACES, useValue: [ADMIN, MAIN] },
        {
          provide: AppStateService,
          useValue: { contextScope, language: signal('es'), tenant: signal('acme') },
        },
        provideRouter([
          {
            path: ':language/:tenant',
            children: workspaceRoutes([MAIN, ADMIN], {} as any, {} as any),
          },
        ]),
      ],
    });
  });

  it('starts in the default workspace (the one without path) and scopes the context to it', () => {
    const service = TestBed.inject(WorkspaceStateService);
    expect(service.active().name).toBe('main');
    expect(service.nav()).toBe(MAIN.nav);
    expect(contextScope()).toBe('main');
  });

  it('follows the workspace of the route it navigates to', async () => {
    const service = TestBed.inject(WorkspaceStateService);
    const router = TestBed.inject(Router);

    await router.navigateByUrl('/es/acme/@admin/clients');
    expect(service.active().name).toBe('admin');
    expect(contextScope()).toBe('admin');

    await router.navigateByUrl('/es/acme/clients');
    expect(service.active().name).toBe('main');
    expect(contextScope()).toBe('main');
  });

  it('builds links inside the active workspace or another one', () => {
    const service = TestBed.inject(WorkspaceStateService);
    expect(service.link('clients')).toEqual(['/', 'es', 'acme', 'clients']);
    expect(service.link('clients', 'admin')).toEqual(['/', 'es', 'acme', '@admin', 'clients']);
    expect(service.link(undefined, 'admin')).toEqual(['/', 'es', 'acme', '@admin']);
    expect(service.url('clients', 'admin')).toBe('es/acme/@admin/clients');
  });
});

describe('workspaceRoutes', () => {
  it('puts the workspaces with a segment before the default one and tags them', () => {
    const routes = workspaceRoutes([MAIN, ADMIN], {} as any, {} as any);
    expect(routes.map((route) => route.path)).toEqual(['@admin', '']);
    expect(routes.map((route) => route.data?.['workspace'])).toEqual(['admin', 'main']);
    expect(routes[0].children?.[0].path).toBe('clients');
  });
});
